        rom[450] = 188'hb86df70d2ee193dc30328f062c68f162ca8f262ce8f362c;
        rom[451] = 188'hb86fb70d66e19adc31178f522d38f422df8f722db8f622d;
        rom[452] = 188'hb86b370df6e188dc33559b5a7d19b4a7dd9b7a7d99b6a7d;
        rom[453] = 188'hb869770dbee181dc327a9fa66ee9fb66e29f866e69f966e;
        rom[454] = 188'hb866b70c46e1bedc3599abaabedabbabe1ab8abe5ab9abe;
        rom[455] = 188'hb864f70c0ee1b7dc34bcabfebf8abeebf4abdebf0abcebf;
        rom[456] = 188'hb860770c9ee1a5dc36febff6efabfe6ef6bfd6ef2bfc6ef;
        rom[457] = 188'hb862370cd6e1acdc37ddb83ae09b82ae05b81ae01b80ae0;
        rom[458] = 188'hec83720ac827206c817202c80720;
        rom[459] = 188'hbc82320fc833203c803207c81320;
        rom[460] = 188'h9d82b60dd83b601d80b605d81b60;
        rom[461] = 188'h6d817602d80760ed83760ad82760;
        rom[462] = 188'h5e81ba01e80ba0de83ba09e82ba0;
        rom[463] = 188'he80fa04e81fa08e82fa0ce83fa0;
        rom[464] = 188'h2f807e06f817e0af827e0ef837e0;
        rom[465] = 188'h1f803e01f803e01f803e01f803e0;
    end
    reg wv = 1'b0;                       // a ROM word is being executed this clock
    reg [WIDTH-1:0] word_r = 0;
    wire [WIDTH-1:0] word = wv ? word_r : {WIDTH{1'b0}};

    // ---------------------------------------------------------------- sequencer
    // start in cycle c0 -> run (ROM addresses) in c0+1 .. c0+NW, word k visible in c0+2+k,
    // the last word executes in c0+NW+1 and done is high in c0+NW+2: cycles = NW + 2.
    reg run = 1'b0, inv_r = 1'b0;
    reg [8:0] pc = 0, end_pc = 0;
    reg [15:0] cyc = 0;
    assign busy = run | wv | done;
    assign cycles = cyc;
    always @(posedge clk) begin
        done <= 1'b0;
        // address gated by `run`: a real gate between the pc flip-flops and the block-RAM
        // address pins (a direct flip-flop drive fails nextpnr's Gowin BSRAM hold check)
        word_r <= rom[pc & {PCW{run}}];
        wv <= run;
        if (rst) begin
            run <= 1'b0; wv <= 1'b0;
        end else if (start && !(run | wv)) begin      // also accepted in the done clock
            run <= 1'b1; inv_r <= inv; cyc <= 16'd1;
            pc     <= inv ? NW_F : 0;
            end_pc <= inv ? TOTAL - 1 : NW_F - 1;
        end else if (run | wv) begin
            cyc <= cyc + 1'b1;
            if (run) begin
                pc <= pc + 1'b1;
                if (pc == end_pc) run <= 1'b0;
            end
            if (wv && !run) done <= 1'b1;
        end
    end

    // ---------------------------------------------------------------- host address decode
    wire [BB-1:0] h_bank = {
^(h_idx & 8'b01110100), ^(h_idx & 8'b01101010), ^(h_idx & 8'b11011001)};
    wire [AW-1:0] h_addr = {h_idx[7], h_idx[6], h_idx[5], h_idx[4], h_idx[3]};
    reg  [BB-1:0] h_bank_q = 0;
    always @(posedge clk) h_bank_q <= h_bank;

    // ---------------------------------------------------------------- banks
    wire [12*B-1:0] rd_flat;
    wire [12*8-1:0] outs_flat;
    (* ram_style = "block" *) reg [11:0] mem0 [0:31];
    reg [11:0] rd0 = 0;
    reg [11:0] wdr0 = 0;                 // write-crossbar register
    wire [AW-1:0] ra0 = wv ? word[4:0] : h_addr;
    wire [BB-1:0] wsel0 = word[13:11];
    wire          ctl_we0 = word[5];
    wire [11:0]   wdsel0 = outs_flat[wsel0 * 12 +: 12];
    wire [11:0]   wd0  = wv ? wdr0 : h_wdata;
    wire          we0  = wv ? ctl_we0 : (h_we & (h_bank == 0));
    wire [AW-1:0] wa0  = wv ? word[10:6] : h_addr;
    always @(posedge clk) begin
        if (we0) mem0[wa0] <= wd0;
        rd0 <= mem0[ra0];
        wdr0 <= wdsel0;
    end
    assign rd_flat[11:0] = rd0;
    (* ram_style = "block" *) reg [11:0] mem1 [0:31];
    reg [11:0] rd1 = 0;
    reg [11:0] wdr1 = 0;                 // write-crossbar register
    wire [AW-1:0] ra1 = wv ? word[18:14] : h_addr;
    wire [BB-1:0] wsel1 = word[27:25];
    wire          ctl_we1 = word[19];
    wire [11:0]   wdsel1 = outs_flat[wsel1 * 12 +: 12];
    wire [11:0]   wd1  = wv ? wdr1 : h_wdata;
    wire          we1  = wv ? ctl_we1 : (h_we & (h_bank == 1));
    wire [AW-1:0] wa1  = wv ? word[24:20] : h_addr;
    always @(posedge clk) begin
        if (we1) mem1[wa1] <= wd1;
        rd1 <= mem1[ra1];
        wdr1 <= wdsel1;
    end
    assign rd_flat[23:12] = rd1;
    (* ram_style = "block" *) reg [11:0] mem2 [0:31];
    reg [11:0] rd2 = 0;
    reg [11:0] wdr2 = 0;                 // write-crossbar register
    wire [AW-1:0] ra2 = wv ? word[32:28] : h_addr;
    wire [BB-1:0] wsel2 = word[41:39];
    wire          ctl_we2 = word[33];
    wire [11:0]   wdsel2 = outs_flat[wsel2 * 12 +: 12];
    wire [11:0]   wd2  = wv ? wdr2 : h_wdata;
    wire          we2  = wv ? ctl_we2 : (h_we & (h_bank == 2));
    wire [AW-1:0] wa2  = wv ? word[38:34] : h_addr;
    always @(posedge clk) begin
        if (we2) mem2[wa2] <= wd2;
        rd2 <= mem2[ra2];
        wdr2 <= wdsel2;
    end
    assign rd_flat[35:24] = rd2;
    (* ram_style = "block" *) reg [11:0] mem3 [0:31];
    reg [11:0] rd3 = 0;
    reg [11:0] wdr3 = 0;                 // write-crossbar register
    wire [AW-1:0] ra3 = wv ? word[46:42] : h_addr;
    wire [BB-1:0] wsel3 = word[55:53];
    wire          ctl_we3 = word[47];
    wire [11:0]   wdsel3 = outs_flat[wsel3 * 12 +: 12];
    wire [11:0]   wd3  = wv ? wdr3 : h_wdata;
    wire          we3  = wv ? ctl_we3 : (h_we & (h_bank == 3));
    wire [AW-1:0] wa3  = wv ? word[52:48] : h_addr;
    always @(posedge clk) begin
        if (we3) mem3[wa3] <= wd3;
        rd3 <= mem3[ra3];
        wdr3 <= wdsel3;
    end
    assign rd_flat[47:36] = rd3;
    (* ram_style = "block" *) reg [11:0] mem4 [0:31];
    reg [11:0] rd4 = 0;
    reg [11:0] wdr4 = 0;                 // write-crossbar register
    wire [AW-1:0] ra4 = wv ? word[60:56] : h_addr;
    wire [BB-1:0] wsel4 = word[69:67];
    wire          ctl_we4 = word[61];
    wire [11:0]   wdsel4 = outs_flat[wsel4 * 12 +: 12];
    wire [11:0]   wd4  = wv ? wdr4 : h_wdata;
    wire          we4  = wv ? ctl_we4 : (h_we & (h_bank == 4));
    wire [AW-1:0] wa4  = wv ? word[66:62] : h_addr;
    always @(posedge clk) begin
        if (we4) mem4[wa4] <= wd4;
        rd4 <= mem4[ra4];
        wdr4 <= wdsel4;
    end
    assign rd_flat[59:48] = rd4;
    (* ram_style = "block" *) reg [11:0] mem5 [0:31];
    reg [11:0] rd5 = 0;
    reg [11:0] wdr5 = 0;                 // write-crossbar register
    wire [AW-1:0] ra5 = wv ? word[74:70] : h_addr;
