    wire          we5  = wv ? ctl_we5 : (h_we & (h_bank == 5));
    wire [AW-1:0] wa5  = wv ? word[80:76] : h_addr;
    always @(posedge clk) begin
        if (we5) mem5[wa5] <= wd5;
