    end
    assign rd_flat[71:60] = rd5;
    (* ram_style = "block" *) reg [11:0] mem6 [0:31];
    reg [11:0] rd6 = 0;
    reg [11:0] wdr6 = 0;                 // write-crossbar register
    wire [AW-1:0] ra6 = wv ? word[88:84] : h_addr;
    wire [BB-1:0] wsel6 = word[97:95];
    wire          ctl_we6 = word[89];
    wire [11:0]   wdsel6 = outs_flat[wsel6 * 12 +: 12];
    wire [11:0]   wd6  = wv ? wdr6 : h_wdata;
    wire          we6  = wv ? ctl_we6 : (h_we & (h_bank == 6));
    wire [AW-1:0] wa6  = wv ? word[94:90] : h_addr;
    always @(posedge clk) begin
        if (we6) mem6[wa6] <= wd6;
        rd6 <= mem6[ra6];
        wdr6 <= wdsel6;
    end
    assign rd_flat[83:72] = rd6;
    (* ram_style = "block" *) reg [11:0] mem7 [0:31];
    reg [11:0] rd7 = 0;
    reg [11:0] wdr7 = 0;                 // write-crossbar register
    wire [AW-1:0] ra7 = wv ? word[102:98] : h_addr;
    wire [BB-1:0] wsel7 = word[111:109];
    wire          ctl_we7 = word[103];
    wire [11:0]   wdsel7 = outs_flat[wsel7 * 12 +: 12];
    wire [11:0]   wd7  = wv ? wdr7 : h_wdata;
    wire          we7  = wv ? ctl_we7 : (h_we & (h_bank == 7));
    wire [AW-1:0] wa7  = wv ? word[108:104] : h_addr;
    always @(posedge clk) begin
        if (we7) mem7[wa7] <= wd7;
        rd7 <= mem7[ra7];
        wdr7 <= wdsel7;
    end
    assign rd_flat[95:84] = rd7;
    assign h_rdata = rd_flat[h_bank_q * 12 +: 12];

    // ---------------------------------------------------------------- lanes
    reg [11:0] a_in0 = 0, b_in0 = 0, z_in0 = 0;
    reg        v_in0 = 1'b0;
    always @(posedge clk) begin
        a_in0 <= rd_flat[word[115:113] * 12 +: 12];
        b_in0 <= rd_flat[word[118:116] * 12 +: 12];
        z_in0 <= word[130:119];
        v_in0 <= word[112];
    end
    wire        vo0;
    wire [11:0] o0_0, o1_0;
    mlkem_bfly lane0 (.clk(clk), .rst(rst), .v_in(v_in0), .mode(inv_r), .a(a_in0), .b(b_in0),
                        .z(z_in0), .v_out(vo0), .o0(o0_0), .o1(o1_0));
    assign outs_flat[11:0] = o0_0;
    assign outs_flat[23:12] = o1_0;
    reg [11:0] a_in1 = 0, b_in1 = 0, z_in1 = 0;
    reg        v_in1 = 1'b0;
    always @(posedge clk) begin
        a_in1 <= rd_flat[word[134:132] * 12 +: 12];
        b_in1 <= rd_flat[word[137:135] * 12 +: 12];
        z_in1 <= word[149:138];
        v_in1 <= word[131];
    end
    wire        vo1;
    wire [11:0] o0_1, o1_1;
    mlkem_bfly lane1 (.clk(clk), .rst(rst), .v_in(v_in1), .mode(inv_r), .a(a_in1), .b(b_in1),
                        .z(z_in1), .v_out(vo1), .o0(o0_1), .o1(o1_1));
    assign outs_flat[35:24] = o0_1;
    assign outs_flat[47:36] = o1_1;
    reg [11:0] a_in2 = 0, b_in2 = 0, z_in2 = 0;
    reg        v_in2 = 1'b0;
    always @(posedge clk) begin
        a_in2 <= rd_flat[word[153:151] * 12 +: 12];
        b_in2 <= rd_flat[word[156:154] * 12 +: 12];
        z_in2 <= word[168:157];
        v_in2 <= word[150];
    end
    wire        vo2;
    wire [11:0] o0_2, o1_2;
    mlkem_bfly lane2 (.clk(clk), .rst(rst), .v_in(v_in2), .mode(inv_r), .a(a_in2), .b(b_in2),
                        .z(z_in2), .v_out(vo2), .o0(o0_2), .o1(o1_2));
    assign outs_flat[59:48] = o0_2;
    assign outs_flat[71:60] = o1_2;
    reg [11:0] a_in3 = 0, b_in3 = 0, z_in3 = 0;
    reg        v_in3 = 1'b0;
    always @(posedge clk) begin
        a_in3 <= rd_flat[word[172:170] * 12 +: 12];
        b_in3 <= rd_flat[word[175:173] * 12 +: 12];
        z_in3 <= word[187:176];
        v_in3 <= word[169];
    end
    wire        vo3;
    wire [11:0] o0_3, o1_3;
    mlkem_bfly lane3 (.clk(clk), .rst(rst), .v_in(v_in3), .mode(inv_r), .a(a_in3), .b(b_in3),
                        .z(z_in3), .v_out(vo3), .o0(o0_3), .o1(o1_3));
    assign outs_flat[83:72] = o0_3;
    assign outs_flat[95:84] = o1_3;
endmodule
